  ('m3-time-01-a1'::text, 'en'::text, 'Say what day it is today, yesterday and tomorrow.'::text),
  ('m3-time-01-a2'::text, 'en'::text, 'Show me today on the strip. Then yesterday, then tomorrow.'::text),
  ('m3-time-02-a1'::text, 'en'::text, 'Tell me what you do on each day of the week.'::text),
  ('m3-time-02-a2'::text, 'en'::text, 'Show today on the strip, then yesterday, then tomorrow.'::text),
  ('m3-time-03-a1'::text, 'en'::text, 'Put the object in front of you. Now behind you. Now beside you.'::text),
  ('m3-time-03-a2'::text, 'en'::text, 'Tell me where the object is, without pointing.'::text),
  ('m3-time-04-a1'::text, 'en'::text, 'Close your eyes. I hide the object; find it using my words.'::text),
  ('m3-time-04-a2'::text, 'en'::text, 'Tell me how to go from the door to your place.'::text),
  ('m3-time-05-a1'::text, 'en'::text, 'Put on each day what you do that day.'::text),
  ('m3-time-05-a2'::text, 'en'::text, 'Is school before or after the market?'::text),
  ('m3-time-06-a1'::text, 'en'::text, 'Put the steps in order: first, then, at the end.'::text),
  ('m3-time-06-a2'::text, 'en'::text, 'I say a step; you say the next one.'::text),
  ('m3-time-07-a1'::text, 'en'::text, 'Put the three moments of the story in order.'::text),
  ('m3-time-07-a2'::text, 'en'::text, 'Tell me a different ending for the story.'::text),
  ('m3-time-08-a1'::text, 'en'::text, 'Say today’s date, all of it, on your own.'::text),
  ('m3-time-08-a2'::text, 'en'::text, 'Put the days of the week in order, without the model.'::text),
  ('m3-world-01-a1'::text, 'en'::text, 'Find the places on your body that bend, and move them.'::text),
  ('m3-world-01-a2'::text, 'en'::text, 'Draw yourself running or dancing.'::text),
  ('m3-world-02-a1'::text, 'en'::text, 'Choose an animal you know and name its parts.'::text),
  ('m3-world-02-a2'::text, 'en'::text, 'Say what your animal needs to live.'::text),
  ('m3-world-03-a1'::text, 'en'::text, 'Look at the plant. Show me its leaves, its stem, its roots.'::text),
  ('m3-world-03-a2'::text, 'en'::text, 'Say what a plant needs to live.'::text),
  ('m3-world-04-a1'::text, 'en'::text, 'I name a joint; you move only that one.'::text),
  ('m3-world-04-a2'::text, 'en'::text, 'Draw a person with bent arms.'::text),
  ('m3-world-05-a1'::text, 'en'::text, 'Compare two animals: what is the same, what is different?'::text),
  ('m3-world-05-a2'::text, 'en'::text, 'Draw your favourite animal with all its parts.'::text),
  ('m3-world-06-a1'::text, 'en'::text, 'Choose an animal or a plant and say what it needs.'::text),
  ('m3-world-06-a2'::text, 'en'::text, 'Look closely and tell me what you notice today.'::text),
  ('m3-world-07-a1'::text, 'en'::text, 'Draw yourself doing your favourite movement of the month.'::text),
  ('m3-world-07-a2'::text, 'en'::text, 'Show me what bends when you do that movement.'::text)$$,
'public.activity_scaffolds matches content/'
);
