  ('maternelle-cycle1-cd-2026'::text, 'TIME-SPACE-S02-C03-O01'::text, 'TIME-SPACE-S02-C03'::text, 1::smallint, 'Explorer les différents lieux de l’école et leur associer des éléments caractéristiques observés.'::text, null::text, 'official'::text, 'programme-2026'::text, 23::smallint),
  ('maternelle-cycle1-cd-2026'::text, 'TIME-SPACE-S02-C03-O02'::text, 'TIME-SPACE-S02-C03'::text, 2::smallint, 'Caractériser l’environnement extérieur proche de l’école.'::text, null::text, 'official'::text, 'programme-2026'::text, 23::smallint),
  ('maternelle-cycle1-cd-2026'::text, 'TIME-SPACE-S02-C03-O03'::text, 'TIME-SPACE-S02-C03'::text, 3::smallint, 'Découvrir des espaces moins familiers.'::text, null::text, 'official'::text, 'programme-2026'::text, 23::smallint),
