  is distinct from (excluded.curriculum_id, excluded.domain_code, excluded.title, excluded.summary, excluded.stage, excluded.difficulty, excluded.theme_id, excluded.parent_guidance, excluded.origin, excluded.status, excluded.reviewer, excluded.reviewer_role, excluded.reviewed_on, excluded.reviewed_digest, excluded.review_notes, excluded.review_kind, excluded.review_outcome);

