insert into public.annual_plan_phases (plan_id, code, name, from_day, to_day, focus)
values
  ('maternelle-1-2026-2027'::text, 'P1'::text, 'Période 1 (trimestre 1)'::text, 1::smallint, 47::smallint, 'Rentrée : oser parler à l’adulte, nommer ce qui est là, compter jusqu’à trois, bouger et s’arrêter.'::text),
  ('maternelle-1-2026-2027'::text, 'P2'::text, 'Période 2 (trimestre 1)'::text, 48::smallint, 79::smallint, 'Installer le vocabulaire du quotidien ; écouter des histoires courtes ; trier par la forme.'::text),
  ('maternelle-1-2026-2027'::text, 'P3'::text, 'Période 3 (trimestre 2)'::text, 80::smallint, 107::smallint, 'Dire ce qu’on fait et ce qu’on a fait ; petites collections jusqu’à quatre ; premiers tracés.'::text),
  ('maternelle-1-2026-2027'::text, 'P4'::text, 'Période 4 (trimestre 2)'::text, 108::smallint, 127::smallint, 'Comptines et sons de la langue ; comparer des longueurs ; motifs répétitifs simples.'::text),
  ('maternelle-1-2026-2027'::text, 'P5'::text, 'Période 5 (trimestre 3)'::text, 128::smallint, 160::smallint, 'Composer et décomposer deux et trois ; se repérer dans l’espace proche ; matières et objets.'::text),
  ('maternelle-1-2026-2027'::text, 'P6'::text, 'Période 6 (trimestre 3)'::text, 161::smallint, 189::smallint, 'Reprendre toute l’année en jouant : ce qui est su doit être redit, remontré, rejoué.'::text),
  ('maternelle-3-2026-2027'::text, 'P1'::text, 'Période 1 (trimestre 1)'::text, 1::smallint, 47::smallint, 'Rentrée : entrer dans le français parlé, compter de petites collections, installer le rituel quotidien.'::text),
  ('maternelle-3-2026-2027'::text, 'P2'::text, 'Période 2 (trimestre 1)'::text, 48::smallint, 79::smallint, 'Consolider l’oral et les premières quantités ; entrer dans la conscience des syllabes.'::text),
  ('maternelle-3-2026-2027'::text, 'P3'::text, 'Période 3 (trimestre 2)'::text, 80::smallint, 107::smallint, 'Rimes, phonèmes et premières lettres ; problèmes de parties et de tout.'::text),
  ('maternelle-3-2026-2027'::text, 'P4'::text, 'Période 4 (trimestre 2)'::text, 108::smallint, 127::smallint, 'Écriture des chiffres et des lettres ; comparer longueurs et masses.'::text),
  ('maternelle-3-2026-2027'::text, 'P5'::text, 'Période 5 (trimestre 3)'::text, 128::smallint, 160::smallint, 'Principe alphabétique et premiers écrits ; motifs et repères dans l’année.'::text),
  ('maternelle-3-2026-2027'::text, 'P6'::text, 'Période 6 (trimestre 3)'::text, 161::smallint, 189::smallint, 'Consolidation de l’année et préparation de l’entrée en primaire.'::text)
on conflict (plan_id, code) do update set
  name = excluded.name,
  from_day = excluded.from_day,
  to_day = excluded.to_day,
  focus = excluded.focus
where (annual_plan_phases.name, annual_plan_phases.from_day, annual_plan_phases.to_day, annual_plan_phases.focus)
  is distinct from (excluded.name, excluded.from_day, excluded.to_day, excluded.focus);

