select bag_eq(
$$select text_id, position, line from public.teaching_text_lines$$,
$$values
  ('bibi-la-chevre-curieuse'::text, 1::smallint, 'Bibi est une chèvre blanche avec une tache noire sur l’oreille.'::text),
  ('bibi-la-chevre-curieuse'::text, 10::smallint, 'Alors elle coupe de l’herbe, beaucoup d’herbe, et elle la donne à Bibi.'::text),
  ('bibi-la-chevre-curieuse'::text, 11::smallint, '« Voilà ton repas à toi, dit-elle. Les légumes, c’est pour nous. »'::text),
  ('bibi-la-chevre-curieuse'::text, 12::smallint, 'Depuis ce jour, Bibi a son tas d’herbe, et le jardin a sa barrière bien fermée.'::text),
  ('bibi-la-chevre-curieuse'::text, 2::smallint, 'Bibi veut toujours savoir ce qu’il y a plus loin.'::text),
  ('bibi-la-chevre-curieuse'::text, 3::smallint, 'Un jour, elle pousse la barrière avec sa tête, et la barrière s’ouvre.'::text),
  ('bibi-la-chevre-curieuse'::text, 4::smallint, 'Bibi marche jusqu’au jardin. Dans le jardin, il y a des feuilles vertes, bien rangées.'::text),
  ('bibi-la-chevre-curieuse'::text, 5::smallint, 'Elle mange une feuille. Puis deux. Puis trois. C’est délicieux.'::text),
  ('bibi-la-chevre-curieuse'::text, 6::smallint, 'Mais ce jardin, c’est le jardin de mama Lelo. Et ces feuilles, ce sont ses légumes.'::text),
  ('bibi-la-chevre-curieuse'::text, 7::smallint, 'Mama Lelo arrive. « Bibi ! Encore toi ! »'::text),
  ('bibi-la-chevre-curieuse'::text, 8::smallint, 'Bibi baisse la tête. Elle sait qu’elle a fait une bêtise.'::text),
  ('bibi-la-chevre-curieuse'::text, 9::smallint, 'Mama Lelo réfléchit. Une chèvre a besoin de manger, c’est vrai. Mais pas dans son jardin.'::text),
  ('bonjour-bonjour'::text, 1::smallint, 'Bonjour, bonjour,'::text),
  ('bonjour-bonjour'::text, 2::smallint, 'le soleil est levé.'::text),
  ('bonjour-bonjour'::text, 3::smallint, 'Bonjour, bonjour,'::text),
  ('bonjour-bonjour'::text, 4::smallint, 'la journée peut commencer.'::text),
  ('bonjour-bonjour'::text, 5::smallint, 'Je dis bonjour à toi,'::text),
  ('bonjour-bonjour'::text, 6::smallint, 'tu dis bonjour à moi,'::text),
  ('bonjour-bonjour'::text, 7::smallint, 'et on se donne la main,'::text),
  ('bonjour-bonjour'::text, 8::smallint, 'une fois, deux fois, trois !'::text),
  ('comptine-bonjour-petit'::text, 1::smallint, 'Bonjour, bonjour, petit bonjour.'::text),
  ('comptine-bonjour-petit'::text, 2::smallint, 'Je dis bonjour à qui est là.'::text),
  ('comptine-bonjour-petit'::text, 3::smallint, 'Bonjour la main, bonjour le pied,'::text),
  ('comptine-bonjour-petit'::text, 4::smallint, 'bonjour, bonjour, et me voilà.'::text),
  ('comptine-je-marche'::text, 1::smallint, 'Je marche, je marche, je marche,'::text),
  ('comptine-je-marche'::text, 2::smallint, 'et hop ! je m’arrête.'::text),
  ('comptine-je-marche'::text, 3::smallint, 'Je marche, je marche, je marche,'::text),
  ('comptine-je-marche'::text, 4::smallint, 'et hop ! je m’assois.'::text),
  ('comptine-la-pluie-tombe'::text, 1::smallint, 'La pluie tombe sur le toit :'::text),
  ('comptine-la-pluie-tombe'::text, 2::smallint, 'plic, plic, plic.'::text),
  ('comptine-la-pluie-tombe'::text, 3::smallint, 'La pluie tombe sur ma main :'::text),
  ('comptine-la-pluie-tombe'::text, 4::smallint, 'ploc, ploc, ploc.'::text),
  ('comptine-la-pluie-tombe'::text, 5::smallint, 'Et puis plus rien. Le soleil revient.'::text),
  ('comptine-le-petit-seau'::text, 1::smallint, 'Dans mon seau il y a de l’eau,'::text),
  ('comptine-le-petit-seau'::text, 2::smallint, 'dans ma main il y a le seau,'::text),
  ('comptine-le-petit-seau'::text, 3::smallint, 'sur ma tête il n’y a rien —'::text),
  ('comptine-le-petit-seau'::text, 4::smallint, 'sur ma tête il y a ma main !'::text),
  ('comptine-un-deux-trois-mains'::text, 1::smallint, 'Un, deux, trois,'::text),
  ('comptine-un-deux-trois-mains'::text, 2::smallint, 'mes mains sont là.'::text),
  ('comptine-un-deux-trois-mains'::text, 3::smallint, 'Un, deux, trois,'::text),
  ('comptine-un-deux-trois-mains'::text, 4::smallint, 'je les cache… les voilà !'::text),
  ('histoire-le-seau-de-lisa'::text, 1::smallint, 'Lisa veut de l’eau. Elle cherche son seau.'::text),
  ('histoire-le-seau-de-lisa'::text, 2::smallint, 'Le seau n’est pas sur la table.'::text),
  ('histoire-le-seau-de-lisa'::text, 3::smallint, 'Lisa regarde sous la table : pas de seau.'::text),
  ('histoire-le-seau-de-lisa'::text, 4::smallint, 'Lisa regarde derrière la porte : pas de seau.'::text),
  ('histoire-le-seau-de-lisa'::text, 5::smallint, 'Maman dit : « Regarde sur la chaise. »'::text),
  ('histoire-le-seau-de-lisa'::text, 6::smallint, 'Le seau est sur la chaise ! Lisa prend son seau.'::text),
  ('histoire-le-seau-de-lisa'::text, 7::smallint, 'Maman verse de l’eau dans le seau.'::text),
  ('histoire-le-seau-de-lisa'::text, 8::smallint, 'Lisa sourit : elle a son eau.'::text),
  ('histoire-tika-se-leve'::text, 1::smallint, 'Le matin, Tika ouvre les yeux.'::text),
  ('histoire-tika-se-leve'::text, 2::smallint, 'Tika se lève. Tika met un pied, puis l’autre pied.'::text),
  ('histoire-tika-se-leve'::text, 3::smallint, 'Tika boit. Tika mange.'::text),
  ('histoire-tika-se-leve'::text, 4::smallint, 'Puis Tika joue, joue, joue.'::text),
  ('histoire-tika-se-leve'::text, 5::smallint, 'Le soir, Tika est fatigué.'::text),
  ('histoire-tika-se-leve'::text, 6::smallint, 'Tika ferme les yeux. Bonne nuit, Tika.'::text),
  ('kumu-le-petit-poussin'::text, 1::smallint, 'Kumu est un petit poussin jaune. Il vit derrière la maison, avec sa maman poule.'::text),
  ('kumu-le-petit-poussin'::text, 10::smallint, 'Maman poule ouvre son aile. Kumu se cache dessous. Il est bien au chaud.'::text),
  ('kumu-le-petit-poussin'::text, 11::smallint, '« La prochaine fois, dit maman poule, tu m’appelles avant de sortir. »'::text),
  ('kumu-le-petit-poussin'::text, 12::smallint, 'Et Kumu répond : « Piou ! », ce qui veut dire oui.'::text),
  ('kumu-le-petit-poussin'::text, 2::smallint, 'Un matin, Kumu voit la porte du poulailler ouverte. Il sort tout seul, sans rien dire.'::text),
  ('kumu-le-petit-poussin'::text, 3::smallint, 'Dehors, tout est grand. L’herbe est grande. Le manguier est grand. Le seau est grand.'::text),
  ('kumu-le-petit-poussin'::text, 4::smallint, 'Kumu marche, marche, marche. Puis il s’arrête. Il ne voit plus la maison.'::text),
  ('kumu-le-petit-poussin'::text, 5::smallint, '« Piou ! Piou ! » Kumu appelle. Personne ne répond.'::text),
  ('kumu-le-petit-poussin'::text, 6::smallint, 'Un lézard passe. « Tu as vu ma maman ? » demande Kumu. « Non », dit le lézard, et il file.'::text),
  ('kumu-le-petit-poussin'::text, 7::smallint, 'Une chèvre passe. « Tu as vu ma maman ? » demande Kumu. « Non », dit la chèvre, et elle mange une feuille.'::text),
  ('kumu-le-petit-poussin'::text, 8::smallint, 'Alors Kumu ferme les yeux et il écoute. Il entend : « Cot ! Cot ! Cot ! »'::text),
  ('kumu-le-petit-poussin'::text, 9::smallint, 'C’est la voix de sa maman ! Kumu court vers la voix, et il arrive au poulailler.'::text),
  ('la-mangue-partagee'::text, 1::smallint, 'Ilunga trouve une grosse mangue sous l’arbre. Une seule.'::text),
  ('la-mangue-partagee'::text, 10::smallint, 'Et la mangue, partagée en trois, a un gout encore meilleur.'::text),
  ('la-mangue-partagee'::text, 2::smallint, 'Il la met dans ses deux mains. Elle est lourde, et elle sent très bon.'::text),
  ('la-mangue-partagee'::text, 3::smallint, 'Ilunga s’assoit pour la manger tout seul.'::text),
  ('la-mangue-partagee'::text, 4::smallint, 'Mais voilà Ama, sa voisine. Et voilà Tito, son petit frère. Ils regardent la mangue.'::text),
  ('la-mangue-partagee'::text, 5::smallint, 'Ils sont trois, et il y a une seule mangue.'::text),
  ('la-mangue-partagee'::text, 6::smallint, 'Ilunga réfléchit. Une mangue, trois enfants. Comment faire ?'::text),
  ('la-mangue-partagee'::text, 7::smallint, 'Il coupe la mangue en trois morceaux : un, deux, trois.'::text),
  ('la-mangue-partagee'::text, 8::smallint, 'Un morceau pour Ama. Un morceau pour Tito. Un morceau pour lui.'::text),
  ('la-mangue-partagee'::text, 9::smallint, '« Maintenant, dit Ilunga, on a tous quelque chose. »'::text),
  ('la-pluie-sur-le-toit'::text, 1::smallint, 'D’abord, le ciel devient gris. Puis le vent pousse les feuilles.'::text),
  ('la-pluie-sur-le-toit'::text, 10::smallint, 'Tito sort, il met un doigt dessous, et la goutte tombe dans sa main.'::text),
  ('la-pluie-sur-le-toit'::text, 2::smallint, 'Tito regarde par la porte. « Ça va tomber », dit-il.'::text),
  ('la-pluie-sur-le-toit'::text, 3::smallint, 'Et ça tombe. Toc. Toc. Toc.'::text),
  ('la-pluie-sur-le-toit'::text, 4::smallint, 'La pluie frappe sur le toit : toc, toc, toc, toc, toc.'::text),
  ('la-pluie-sur-le-toit'::text, 5::smallint, 'Puis elle frappe plus vite : toctoctoctoctoc.'::text),
  ('la-pluie-sur-le-toit'::text, 6::smallint, 'Tito ferme les yeux et il écoute. La pluie fait de la musique sur le toit.'::text),
  ('la-pluie-sur-le-toit'::text, 7::smallint, 'Dehors, l’eau court par terre. Elle fait des petites rivières entre les cailloux.'::text),
  ('la-pluie-sur-le-toit'::text, 8::smallint, 'Et puis, tout doucement, la pluie s’arrête. Toc… toc… …'::text),
  ('la-pluie-sur-le-toit'::text, 9::smallint, 'Il reste une goutte sur une feuille. Elle brille comme une perle.'::text),
  ('la-semaine-de-kiki'::text, 1::smallint, 'Lundi, Kiki se réveille.'::text),
  ('la-semaine-de-kiki'::text, 2::smallint, 'Mardi, Kiki va à l’école.'::text),
  ('la-semaine-de-kiki'::text, 3::smallint, 'Mercredi, Kiki dessine.'::text),
  ('la-semaine-de-kiki'::text, 4::smallint, 'Jeudi, Kiki chante.'::text),
  ('la-semaine-de-kiki'::text, 5::smallint, 'Vendredi, Kiki danse.'::text),
  ('la-semaine-de-kiki'::text, 6::smallint, 'Samedi, Kiki va au marché.'::text),
  ('la-semaine-de-kiki'::text, 7::smallint, 'Dimanche, Kiki se repose…'::text),
  ('la-semaine-de-kiki'::text, 8::smallint, 'et lundi, ça recommence !'::text),
  ('le-marche-de-mama-lelo'::text, 1::smallint, 'Le samedi, mama Lelo va au marché, et Ama vient avec elle.'::text),
  ('le-marche-de-mama-lelo'::text, 10::smallint, '« Tu as bien travaillé », dit mama Lelo. Et Ama est très fière.'::text),
  ('le-marche-de-mama-lelo'::text, 2::smallint, 'Le marché, c’est plein de couleurs : le rouge des tomates, le vert des feuilles, le jaune des bananes.'::text),
  ('le-marche-de-mama-lelo'::text, 3::smallint, '« Ama, dit mama Lelo, tu comptes avec moi ? »'::text),
  ('le-marche-de-mama-lelo'::text, 4::smallint, 'Elles achètent des tomates : une, deux, trois, quatre, cinq. Cinq tomates dans le panier.'::text),
  ('le-marche-de-mama-lelo'::text, 5::smallint, 'Elles achètent des oignons : un, deux, trois. Trois oignons dans le panier.'::text),
  ('le-marche-de-mama-lelo'::text, 6::smallint, '« Et maintenant, demande mama Lelo, qu’est-ce qu’il y a le plus ? Les tomates ou les oignons ? »'::text),
  ('le-marche-de-mama-lelo'::text, 7::smallint, 'Ama regarde. Cinq, c’est plus que trois. « Les tomates ! » dit-elle.'::text),
  ('le-marche-de-mama-lelo'::text, 8::smallint, 'Sur le chemin du retour, le panier est lourd. Elles le portent à deux, chacune une anse.'::text),
  ('le-marche-de-mama-lelo'::text, 9::smallint, 'À la maison, Ama range : les tomates avec les tomates, les oignons avec les oignons.'::text),
  ('le-premier-jour-de-nsimba'::text, 1::smallint, 'Ce matin, Nsimba met sa chemise, ses chaussures, et son petit sac sur le dos.'::text),
  ('le-premier-jour-de-nsimba'::text, 10::smallint, 'À côté, une fille lui tend un crayon bleu. « Tu veux ? Moi, c’est Amina. »'::text),
  ('le-premier-jour-de-nsimba'::text, 11::smallint, 'Nsimba prend le crayon. Il dessine une maison, un soleil, et deux enfants.'::text),
  ('le-premier-jour-de-nsimba'::text, 12::smallint, 'Le soir, son adulte demande : « Alors, cette école ? »'::text),
  ('le-premier-jour-de-nsimba'::text, 13::smallint, 'Nsimba répond : « Demain, j’y retourne. »'::text),
  ('le-premier-jour-de-nsimba'::text, 2::smallint, 'Aujourd’hui, c’est son premier jour à l’école.'::text),
  ('le-premier-jour-de-nsimba'::text, 3::smallint, 'Sur le chemin, son ventre fait un drôle de nœud. Nsimba serre très fort la main de son adulte.'::text),
  ('le-premier-jour-de-nsimba'::text, 4::smallint, 'Devant le portail, il y a beaucoup d’enfants. Beaucoup de bruit. Beaucoup de pieds.'::text),
  ('le-premier-jour-de-nsimba'::text, 5::smallint, 'Nsimba voudrait rentrer à la maison.'::text),
  ('le-premier-jour-de-nsimba'::text, 6::smallint, 'La maitresse s’accroupit devant lui. « Bonjour. Moi, c’est madame Kalala. Et toi ? »'::text),
  ('le-premier-jour-de-nsimba'::text, 7::smallint, 'Nsimba ne dit rien. Puis, tout doucement : « Nsimba. »'::text),
  ('le-premier-jour-de-nsimba'::text, 8::smallint, '« Viens, Nsimba, dit la maitresse. Ta place est ici, avec ton prénom dessus. »'::text),
  ('le-premier-jour-de-nsimba'::text, 9::smallint, 'Sur la table, il y a son prénom. Rien qu’à lui.'::text),
  ('les-formes-qui-dansent'::text, 1::smallint, 'Le rond tourne, tourne, tourne,'::text),
  ('les-formes-qui-dansent'::text, 2::smallint, 'il n’a pas de coin du tout.'::text),
  ('les-formes-qui-dansent'::text, 3::smallint, 'Le carré a quatre côtés,'::text),
  ('les-formes-qui-dansent'::text, 4::smallint, 'quatre côtés tout pareils.'::text),
  ('les-formes-qui-dansent'::text, 5::smallint, 'Le rectangle est plus long,'::text),
  ('les-formes-qui-dansent'::text, 6::smallint, 'deux petits et deux grands côtés.'::text),
  ('les-formes-qui-dansent'::text, 7::smallint, 'Et le triangle, lui, en a trois :'::text),
  ('les-formes-qui-dansent'::text, 8::smallint, 'un, deux, trois, et c’est fini !'::text),
  ('les-trois-cailloux-de-tito'::text, 1::smallint, 'Tito ramasse un caillou rond. Il le met dans sa poche.'::text),
  ('les-trois-cailloux-de-tito'::text, 10::smallint, 'Sa sœur ouvre la main : c’est bien le caillou pointu.'::text),
  ('les-trois-cailloux-de-tito'::text, 11::smallint, 'Trois cailloux, moins un, ça fait deux. Et deux, plus un, ça refait trois.'::text),
  ('les-trois-cailloux-de-tito'::text, 2::smallint, 'Il ramasse un caillou plat. Il le met dans sa poche.'::text),
  ('les-trois-cailloux-de-tito'::text, 3::smallint, 'Il ramasse un caillou pointu. Il le met dans sa poche. Ça fait trois.'::text),
  ('les-trois-cailloux-de-tito'::text, 4::smallint, 'À la maison, il pose ses trois cailloux sur la table : le rond, le plat, le pointu.'::text),
  ('les-trois-cailloux-de-tito'::text, 5::smallint, 'Sa grande sœur en prend un et le cache derrière son dos.'::text),
  ('les-trois-cailloux-de-tito'::text, 6::smallint, '« Il en reste combien ? » demande-t-elle.'::text),
  ('les-trois-cailloux-de-tito'::text, 7::smallint, 'Tito compte : un, deux. « Deux ! »'::text),
  ('les-trois-cailloux-de-tito'::text, 8::smallint, '« Et qu’est-ce qui manque ? »'::text),
  ('les-trois-cailloux-de-tito'::text, 9::smallint, 'Tito regarde bien. Le rond est là. Le plat est là. « Le pointu ! »'::text),
  ('malo-ne-veut-pas-dormir'::text, 1::smallint, 'Le soir tombe. Malo, le petit chien, ne veut pas dormir.'::text),
  ('malo-ne-veut-pas-dormir'::text, 10::smallint, 'Il se couche en rond, le nez sur la queue.'::text),
  ('malo-ne-veut-pas-dormir'::text, 11::smallint, '« Ah, dit Malo, moi, c’est comme ça que je dors. »'::text),
  ('malo-ne-veut-pas-dormir'::text, 12::smallint, 'Et il dort.'::text),
  ('malo-ne-veut-pas-dormir'::text, 2::smallint, '« Je n’ai pas sommeil ! » dit Malo. Mais ses yeux, eux, ont sommeil.'::text),
  ('malo-ne-veut-pas-dormir'::text, 3::smallint, 'Il va voir le coq. « Coq, comment tu fais pour dormir ? »'::text),
  ('malo-ne-veut-pas-dormir'::text, 4::smallint, '« Moi, dit le coq, je monte sur ma branche et je mets ma tête sous mon aile. »'::text),
  ('malo-ne-veut-pas-dormir'::text, 5::smallint, 'Malo essaie de monter sur la branche. Il tombe. Ça ne marche pas pour un chien.'::text),
  ('malo-ne-veut-pas-dormir'::text, 6::smallint, 'Il va voir le poisson dans le seau. « Poisson, comment tu fais pour dormir ? »'::text),
  ('malo-ne-veut-pas-dormir'::text, 7::smallint, '« Moi, dit le poisson, je dors dans l’eau, les yeux ouverts. »'::text),
  ('malo-ne-veut-pas-dormir'::text, 8::smallint, 'Malo met une patte dans l’eau. Elle est froide. Ça ne marche pas non plus.'::text),
  ('malo-ne-veut-pas-dormir'::text, 9::smallint, 'Alors Malo rentre à la maison. Il tourne une fois, deux fois, trois fois.'::text),
  ('mes-deux-mains'::text, 1::smallint, 'Voici ma tête,'::text),
  ('mes-deux-mains'::text, 2::smallint, 'voici mes épaules,'::text),
  ('mes-deux-mains'::text, 3::smallint, 'voici mes deux mains'::text),
  ('mes-deux-mains'::text, 4::smallint, 'qui montent tout là-haut.'::text),
  ('mes-deux-mains'::text, 5::smallint, 'Voici mes genoux,'::text),
  ('mes-deux-mains'::text, 6::smallint, 'voici mes deux pieds,'::text),
  ('mes-deux-mains'::text, 7::smallint, 'et voici mon ventre'::text),
  ('mes-deux-mains'::text, 8::smallint, 'qui se met à rigoler !'::text),
  ('saute-petit-cabri'::text, 1::smallint, 'Saute, saute, petit cabri,'::text),
  ('saute-petit-cabri'::text, 2::smallint, 'saute une fois, saute deux fois.'::text),
  ('saute-petit-cabri'::text, 3::smallint, 'Cours, cours, petit cabri,'::text),
  ('saute-petit-cabri'::text, 4::smallint, 'cours tout doucement, puis arrête-toi.'::text),
  ('saute-petit-cabri'::text, 5::smallint, 'Tourne, tourne, petit cabri,'::text),
  ('saute-petit-cabri'::text, 6::smallint, 'tourne à droite, tourne à gauche.'::text),
  ('saute-petit-cabri'::text, 7::smallint, 'Et maintenant, petit cabri,'::text),
  ('saute-petit-cabri'::text, 8::smallint, 'assieds-toi et respire tout doux.'::text),
  ('un-deux-trois-je-compte'::text, 1::smallint, 'Un, deux, trois,'::text),
  ('un-deux-trois-je-compte'::text, 2::smallint, 'je compte avec toi.'::text),
  ('un-deux-trois-je-compte'::text, 3::smallint, 'Quatre, cinq, six,'::text),
  ('un-deux-trois-je-compte'::text, 4::smallint, 'des cailloux tout lisses.'::text),
  ('un-deux-trois-je-compte'::text, 5::smallint, 'Sept, huit, neuf,'::text),
  ('un-deux-trois-je-compte'::text, 6::smallint, 'un panier tout neuf.'::text),
  ('un-deux-trois-je-compte'::text, 7::smallint, 'Et dix petits doigts'::text),
  ('un-deux-trois-je-compte'::text, 8::smallint, 'qui comptent avec moi !'::text)$$,
'public.teaching_text_lines is unchanged after re-applying the sync'
);
